const int kDataGlobalCount = (int)(sizeof(kDataGlobals) / sizeof(kDataGlobals[0]));

// Largest data-global start <= addr (containing/owner global index) or -1.
static int DataGlobalNumAt(unsigned long addr)
{
    int lo = 0, hi = kDataGlobalCount - 1, best = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (kDataGlobals[mid].addr <= addr) { best = mid; lo = mid + 1; }
        else { hi = mid - 1; }
    }
    return best;
}

// The global's size is the gap to the next table entry; IDA allocates
// every byte of the address space to exactly one symbol.
static unsigned long DataGlobalSizeAt(int i)
{
    if (i < 0) return 0;
    if (i + 1 < kDataGlobalCount) return kDataGlobals[i + 1].addr - kDataGlobals[i].addr;
    return 0x100;
}

